import{_ as t,o,c as a,a2 as s}from"./chunks/framework.BDCokyix.js";const u=JSON.parse('{"title":"PRD: UI Revamp v0","description":"","frontmatter":{},"headers":[],"relativePath":"architecture/prd/ui-revamp-v0.md","filePath":"architecture/prd/ui-revamp-v0.md","lastUpdated":1780254295000}'),n={name:"architecture/prd/ui-revamp-v0.md"};function r(i,e,d,l,c,p){return o(),a("div",null,[...e[0]||(e[0]=[s(`<h1 id="prd-ui-revamp-v0" tabindex="-1">PRD: UI Revamp v0 <a class="header-anchor" href="#prd-ui-revamp-v0" aria-label="Permalink to &quot;PRD: UI Revamp v0&quot;">​</a></h1><p>Status: <strong>Draft</strong> — open for iteration. Locked decisions move to ADR-0005.</p><h2 id="_1-vision" tabindex="-1">1. Vision <a class="header-anchor" href="#_1-vision" aria-label="Permalink to &quot;1. Vision&quot;">​</a></h2><p>Soma is a Notion-style personal workspace where <strong>the rich text editor is the user&#39;s memory</strong> and <strong>the LLM is the productivity tool that operates on that memory</strong>. Documents, spaces, and notes are the substrate; the assistant turns them into summaries, exercises, plans, agendas, and other artifacts on demand.</p><p>Around that core, the workspace hosts <strong>bots</strong> — capability-holding p2p peers that can be addressed inline with <code>@bot:&lt;name&gt;</code> to receive instructions (e.g. <em>&quot;Check status of @bot:foo&quot;</em>, <em>&quot;Tell @bot:foo to stop accepting users until Jan 15&quot;</em>). Bots are not chat partners; they are programmable members with their own runtimes.</p><h3 id="pillars" tabindex="-1">Pillars <a class="header-anchor" href="#pillars" aria-label="Permalink to &quot;Pillars&quot;">​</a></h3><ol><li><strong>Memory in, intelligence out.</strong> The editor stores everything; the LLM transforms it.</li><li><strong>Dense by default.</strong> Built for 14–16&quot; laptops doing real work. Information per pixel matters more than whitespace.</li><li><strong>One UI system.</strong> No more tapia-vs-soma split. Everything in <code>@soma/ui</code>, themed with Tailwind v4 + DaisyUI v5.</li><li><strong>Composable right area.</strong> Not &quot;a chat panel&quot; — a stackable, splittable panel system. Chat is one panel; history, sub-pages, attached files, agenda, exercise queue are siblings.</li><li><strong>Multi-window for focus tasks.</strong> Typing drills, exams, surveys open in lightweight popup windows so the user keeps working in the main window.</li></ol><h3 id="runtime-ground-truth-post-collapse" tabindex="-1">Runtime ground truth (post-collapse) <a class="header-anchor" href="#runtime-ground-truth-post-collapse" aria-label="Permalink to &quot;Runtime ground truth (post-collapse)&quot;">​</a></h3><p>The daemon and agent runtimes are no longer separate processes. Both ship as library crates (<code>soma-daemon</code>, <code>soma-agentd</code>) embedded in the <code>@soma/node</code> napi addon, loaded directly by the Electron main process. The renderer reaches the daemon via Electron IPC → main → napi → in-process Rust (<code>SomaHandle</code> / <code>DaemonHandle</code>). No gRPC, no UDS — see ADR-0001 (Superseded). This matters for v0 UX because:</p><ul><li>Calls are effectively synchronous from main&#39;s perspective; no socket round-trip to budget for.</li><li>Streaming events from the daemon arrive via <code>ThreadsafeFunction</code> callbacks. Long-lived subscriptions (history feed, agenda, presence, bot handshake status) are cheap — the right-area panels can be live without paying gRPC stream overhead.</li></ul><h2 id="_2-mental-model-llm-vs-bots" tabindex="-1">2. Mental model: LLM vs. Bots <a class="header-anchor" href="#_2-mental-model-llm-vs-bots" aria-label="Permalink to &quot;2. Mental model: LLM vs. Bots&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th>LLM (assistant)</th><th>Bot</th></tr></thead><tbody><tr><td>Role</td><td>Conversational productivity partner</td><td>Programmable peer with capabilities</td></tr><tr><td>Lives in</td><td>A right-area panel (chat)</td><td>p2p network, its own runtime</td></tr><tr><td>Added via</td><td>Space settings → &quot;Connect assistant&quot;</td><td>Space settings → &quot;Add bot&quot;</td></tr><tr><td>Addressed via</td><td>Direct chat in panel</td><td><code>@bot:&lt;name&gt;</code> mention, in chat or document</td></tr><tr><td>Typical input</td><td>Free-form questions, document context</td><td>Instructions / commands</td></tr><tr><td>Typical output</td><td>Prose, summaries, generated content</td><td>Action ack, status, capability-bound side effects</td></tr></tbody></table><p><strong>Both are space members</strong> under the existing capability model (<a href="./../../space-authorization-model">space-authorization-model.md</a>). UI distinguishes them; the auth layer doesn&#39;t.</p><h2 id="_3-layout-system" tabindex="-1">3. Layout system <a class="header-anchor" href="#_3-layout-system" aria-label="Permalink to &quot;3. Layout system&quot;">​</a></h2><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌────────┬──────────────────────────┬──────────────────────────────┐</span></span>
<span class="line"><span>│        │                          │  Right area (panel stack)    │</span></span>
<span class="line"><span>│ Spaces │   Document (TipTap)      │  ┌────────────────────────┐  │</span></span>
<span class="line"><span>│  rail  │                          │  │  Chat (LLM)            │  │</span></span>
<span class="line"><span>│        │                          │  ├────────────────────────┤  │</span></span>
<span class="line"><span>│ ~52px  │   ~minmax(600px, 1fr)    │  │  History / metadata    │  │</span></span>
<span class="line"><span>│        │                          │  ├────────────────────────┤  │</span></span>
<span class="line"><span>│        │                          │  │  Sub-pages             │  │</span></span>
<span class="line"><span>│        │                          │  └────────────────────────┘  │</span></span>
<span class="line"><span>└────────┴──────────────────────────┴──────────────────────────────┘</span></span>
<span class="line"><span>                                       ~320–480px, vertically stacked</span></span>
<span class="line"><span>                                       OR horizontally split (2 cols)</span></span>
<span class="line"><span>                                       OR collapsed to icon strip</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br></div></div><h3 id="right-area-rules" tabindex="-1">Right area rules <a class="header-anchor" href="#right-area-rules" aria-label="Permalink to &quot;Right area rules&quot;">​</a></h3><ul><li><strong>Multi-panel container.</strong> Each panel has: header (title, collapse, close, drag-handle), body, optional footer.</li><li><strong>Stacking.</strong> Default is vertical stack; user can drag a panel to split horizontally (max 2 columns inside the rail).</li><li><strong>Pinning.</strong> Panels are pinned to a space or to a document. Switching documents reflows; pinned-to-space panels persist.</li><li><strong>Sources.</strong> Panels can be opened by: assistant (&quot;show history&quot;), user (panel menu), automation (e.g. opening a doc with attachments auto-shows the attachments panel).</li><li><strong>Collapse, not hide.</strong> Collapsed panels become a vertical icon strip on the rail&#39;s right edge.</li></ul><h3 id="responsive-behavior-editor-stays-the-priority" tabindex="-1">Responsive behavior (editor stays the priority) <a class="header-anchor" href="#responsive-behavior-editor-stays-the-priority" aria-label="Permalink to &quot;Responsive behavior (editor stays the priority)&quot;">​</a></h3><p>Width budgets, in order of degradation as the window shrinks:</p><ol><li><strong>Comfortable (≥ ~1280px usable):</strong> rail + editor + right area docked, multiple panels visible.</li><li><strong>Tight (~960–1280px):</strong> docked right area collapses to icon strip; opening a panel slides it in as a <strong>right-edge drawer with overlay</strong> on top of the editor. Editor never compresses below its readable threshold.</li><li><strong>Very small (&lt; ~960px or compact device):</strong> right area enters <strong>fullscreen-takeover</strong> mode when summoned — editor is hidden under it, dismissing returns to editor. Main content priority = editor; panels only show on demand.</li></ol><p>The same rules apply per-panel: a panel that wants to split horizontally only does so if the rail has the budget. Otherwise the split request stacks vertically instead.</p><h3 id="density-defaults" tabindex="-1">Density defaults <a class="header-anchor" href="#density-defaults" aria-label="Permalink to &quot;Density defaults&quot;">​</a></h3><ul><li>Font sizes: <strong>14px body</strong>, <strong>13px UI-sm</strong> (row metadata, secondary text), <strong>11px UI-xs</strong> (labels, pills).</li><li>Line-height: <strong>1.5</strong> for body, <strong>1.2</strong> for UI chrome. (Bumped from 1.45 after the refero pass — every dense product surveyed runs ~1.5 at 14px; 1.45 visibly compresses two-line metadata.)</li><li>Spacing scale: extend Tailwind with <code>0.5</code> → 2px, <code>1.5</code> → 6px steps. Defaults to <code>2</code>–<code>3</code> spacing (8–12px) for component padding, not <code>4</code>–<code>6</code>.</li><li>Row heights: <strong>32px / 40px / 52px</strong> tiers for dense / cozy / oversized lists.</li><li>Shadows: <strong>one token total</strong>, reserved for modal + popup window only. Everywhere else use 1px borders + bg-step (DaisyUI <code>base-200</code> / <code>base-300</code>).</li><li>Border radius: <code>rounded-md</code> (6px) max for surfaces; <code>rounded-sm</code> for chips/inline.</li></ul><p>Concrete token table lives in <a href="./ui-revamp-v0-refs-files-density">prd/ui-revamp-v0-refs-files-density.md §3</a>.</p><h2 id="_4-flows-to-define-this-prd-locks-them" tabindex="-1">4. Flows to define (this PRD locks them) <a class="header-anchor" href="#_4-flows-to-define-this-prd-locks-them" aria-label="Permalink to &quot;4. Flows to define (this PRD locks them)&quot;">​</a></h2><p>Each flow gets a short subsection: trigger, steps, surface, success state. Drafts below; refero pass (step 2 of plan) feeds revisions before lock.</p><h3 id="_4-1-create-a-space" tabindex="-1">4.1 Create a space <a class="header-anchor" href="#_4-1-create-a-space" aria-label="Permalink to &quot;4.1 Create a space&quot;">​</a></h3><p><em>Draft.</em> Trigger: spaces-rail &quot;+&quot; button. Steps: name → privacy (local / shared) → done. No bots, no assistant yet — those are added from settings after creation. Success: routed to empty space with onboarding placeholder.</p><h3 id="_4-2-configure-a-space" tabindex="-1">4.2 Configure a space <a class="header-anchor" href="#_4-2-configure-a-space" aria-label="Permalink to &quot;4.2 Configure a space&quot;">​</a></h3><p><em>Draft.</em> Single settings screen with <strong>horizontal pill/underline tabs</strong> under the page title: General · Members · Assistant · Bots · Sharing · Danger. Each tab is a single screen of sectioned cards.</p><p><strong>Save model — auto-save on blur, no global Save button.</strong> Per-section Save buttons are banned. Errors surface inline under the field; success is silent (the value just persists). Explicit primary actions exist only for <em>initiation</em> (e.g. &quot;Add backend&quot;, &quot;Add bot&quot;) and <em>destructive</em> operations (Danger tab — see below).</p><p><strong>Danger zone</strong> sits on its own card on the Danger tab, red-labelled. <code>Delete space</code> opens an inline slug-confirm form (type the space slug to confirm); the destructive button stays disabled until the typed slug matches.</p><p>See <a href="./ui-revamp-v0-refs-space-lifecycle">prd/ui-revamp-v0-refs-space-lifecycle.md §2</a> for the locked tab IA.</p><h3 id="_4-3-add-an-assistant-llm-to-a-space" tabindex="-1">4.3 Add an assistant (LLM) to a space <a class="header-anchor" href="#_4-3-add-an-assistant-llm-to-a-space" aria-label="Permalink to &quot;4.3 Add an assistant (LLM) to a space&quot;">​</a></h3><p><em>Draft.</em> Soma speaks the <strong>Agent Client Protocol (ACP)</strong> — the same protocol Zed uses — so any ACP-capable backend works: Ollama, LM Studio, Codex, and OpenAI-compatible endpoints via an ACP shim. ACP backends are managed by the embedded <code>soma-agentd</code> runtime; the renderer configures and selects them through the napi <code>SomaHandle</code>, not by dialing services directly. Settings → Assistant tab lists configured backends and lets the user add new ones (transport URL + auth). One backend can be marked default for the space; per-message override happens in the chat header (see 4.5).</p><h3 id="_4-4-add-a-bot-to-a-space-—-v0-priority" tabindex="-1">4.4 Add a bot to a space — <strong>v0 priority</strong> <a class="header-anchor" href="#_4-4-add-a-bot-to-a-space-—-v0-priority" aria-label="Permalink to &quot;4.4 Add a bot to a space — **v0 priority**&quot;">​</a></h3><p>Bots are not discovered automatically. Whoever runs the bot reads its peer address and shares it out-of-band; the adder pastes it into space settings. RBAC controls who can do this — the owner may delegate bot-adding to non-owner roles, optionally constraining what capabilities they can grant.</p><p><em>Draft.</em> Settings → Bots tab. List shows already-added bots with handshake status. &quot;Add bot&quot; opens a 2-step inline form:</p><ol><li><strong>Paste peer address.</strong> Single input. UI validates format on blur. (Future: optional &quot;import from clipboard&quot; / QR scan.)</li><li><strong>Grant capability.</strong> Role is <code>Bot</code>. User picks scope (read/write per resource type — docs, messages, attachments), expiry, alias used in <code>@bot:&lt;alias&gt;</code> mentions. Sign + issue → daemon performs handshake + encryption + space-global registration. Status flips to <code>active</code> when the bot acks.</li></ol><p>Errors surface inline at step 2 (handshake failure, signature reject) — no toast-only failures.</p><p>No floating modals. No multi-step wizard. Two visible steps, one save.</p><p><strong>Backend dependency.</strong> The embedded daemon (in-process via <code>@soma/node</code>) must:</p><ul><li>Accept a &quot;bot peer address&quot; through the <code>SomaHandle</code> / <code>DaemonHandle</code> facade and run the handshake/encryption/registration round-trip.</li><li>Expose <code>list_space_bots</code> (status + capability scope) for the settings UI.</li><li>Enforce delegated bot-add authority based on the inviter&#39;s own capability (RBAC).</li><li>Stream bot status updates over the existing event channel so the bots list stays live without polling.</li></ul><p>It is not yet confirmed whether the daemon already persists registered bots per-space or exposes a handshake entry point — this is a v0 backend item to verify and complete in parallel with the UI work. The API additions live in <a href="./../../../../backend/crates/daemon/src/handle/">backend/crates/daemon/src/handle/</a> and surface through <a href="./../../../../backend/crates/soma-node">backend/crates/soma-node</a>.</p><h3 id="_4-5-chat-with-the-assistant" tabindex="-1">4.5 Chat with the assistant <a class="header-anchor" href="#_4-5-chat-with-the-assistant" aria-label="Permalink to &quot;4.5 Chat with the assistant&quot;">​</a></h3><p><em>Draft.</em> Right-area chat panel. Input at bottom, messages scroll up. Slash menu for actions on current document. <code>@</code> opens a sectioned mention picker — Bots → Documents → Members, in that order. Bot mentions render as pills with a distinct icon and surface tint so the user sees at a glance that the mention will dispatch to a runtime, not the LLM.</p><p><strong>Backend switcher (composer footer, dense).</strong> The active ACP backend sits as a chip in the <strong>composer footer</strong>, not the chat header: <code>&lt;provider-mark&gt; &lt;name&gt; ↕</code>. Click → dropdown with text labels lists configured backends; selection applies to the next message. The dropdown also surfaces &quot;Add backend…&quot; which deep-links to the Assistant settings tab. Header stays empty of provider chrome — saves vertical space and puts the control where the user&#39;s eye is when picking.</p><p><strong>Streaming.</strong> Partial tokens render live. A <code>Thinking…</code> pill covers sub-first-token latency. While streaming, the composer&#39;s send button swaps to a solid round stop. After completion, a chip row appears under the message: <code>↻ Regenerate</code> · <code>Copy</code> · <code>…</code>.</p><h3 id="_4-6-send-an-instruction-to-a-bot" tabindex="-1">4.6 Send an instruction to a bot <a class="header-anchor" href="#_4-6-send-an-instruction-to-a-bot" aria-label="Permalink to &quot;4.6 Send an instruction to a bot&quot;">​</a></h3><p><em>Draft.</em> In chat (v0.1: also from documents): <code>@bot:foo do X</code>. The bot mention renders as a distinct pill. When the composer text begins with <code>@bot:</code>, the send button label flips to <code>Dispatch</code> and the left edge of the composer picks up the bot-mention surface tint — the user sees a different action is about to occur.</p><p>On send, the message routes to the bot&#39;s runtime (via the napi <code>SomaHandle</code>), not the LLM. Rendering in the thread:</p><ul><li><strong>User message</strong> — text up to the <code>@bot:</code> pill in proportional face; instruction body wraps in monospace + <code>$</code> prefix to read as a command.</li><li><strong>Dispatch ack</strong> — collapsed pill between command and reply: <code>bot:foo · dispatched · &lt;timestamp&gt;</code>. Expandable on click to show ACP/handshake trace.</li><li><strong>Bot reply</strong> — bot-attribution pill in the message header; monospace for structured output, proportional for prose.</li><li><strong>Failure</strong> — same chat slot the response would have occupied, monospace + red surface tint, inline <code>Retry</code> chip + <code>Open bot status</code> link. No toast.</li></ul><h3 id="_4-7-open-a-focused-popup-task-10-finger-typing" tabindex="-1">4.7 Open a focused popup task (10-finger typing) <a class="header-anchor" href="#_4-7-open-a-focused-popup-task-10-finger-typing" aria-label="Permalink to &quot;4.7 Open a focused popup task (10-finger typing)&quot;">​</a></h3><p><em>Draft.</em> From <code>/practice</code> exercise detail, &quot;Open in window&quot; → spawns a <code>BrowserWindow</code> with route <code>#/popup/typing/&lt;exercise-id&gt;</code>. Popup renders only <a href="./../../../../desktop/desktop-ui/src/components/tapia/char-display.tsx"><code>CharDisplay</code></a> + input + minimal stats. Main window stays usable. Same mechanism will host future exam/survey popups.</p><p><strong>Popup chrome (locked).</strong> 520×360 default, min-width 480px. Chrome auto-hides to a 28px drag strip on input focus. Glyph cluster on the drag region, flush-right: <strong>pin</strong> (always-on-top toggle, default off) · <strong>restart</strong> · <strong>return-to-main</strong> (closes popup + focuses main, leaves exercise state intact and resumable) · <strong>close</strong>. OS window title = the exercise&#39;s own name (not <code>Soma — Typing</code>) so the popup is identifiable in the dock / window switcher.</p><p><strong>Completion.</strong> Popup closes → <code>app.focus()</code> on main + route to <code>/practice/&lt;id&gt;</code> → single toast <code>Exercise complete · WPM · accuracy · View result</code>.</p><h3 id="_4-8-switch-spaces-documents" tabindex="-1">4.8 Switch spaces / documents <a class="header-anchor" href="#_4-8-switch-spaces-documents" aria-label="Permalink to &quot;4.8 Switch spaces / documents&quot;">​</a></h3><p><em>Draft.</em> Spaces rail = icons only (52px wide). Document tree lives <em>inside</em> the document column header as a breadcrumb + tree popover, not as a third pane. Saves horizontal space.</p><h3 id="_4-9-upload-attach-a-file" tabindex="-1">4.9 Upload / attach a file <a class="header-anchor" href="#_4-9-upload-attach-a-file" aria-label="Permalink to &quot;4.9 Upload / attach a file&quot;">​</a></h3><p><em>Draft.</em> Drag into document or attachments panel. File type detected from content, not just extension (fixes the &quot;ZIP archive&quot; bug for .txt). Inline preview in attachments panel.</p><ul><li><strong>Drag overlay.</strong> 2px dashed accent border on the entire document column (not per-block); single centered &quot;Drop to attach&quot; tile.</li><li><strong>In-document attachment.</strong> Chip-row: type glyph + filename + MIME + size + <code>×</code>. Two per row when width allows.</li><li><strong>Attachments panel.</strong> Dashed dropzone tile <em>above</em> the file list (never as the whole panel). Rows: 16px color-coded file-type glyph + truncated name + faint date subline + always-visible <code>⋯</code>.</li><li><strong>Upload progress.</strong> Inline bar baked into the row background; <code>n%</code> on the right; replaced by size on completion.</li><li><strong>MIME mismatch.</strong> Warning glyph + parenthetical detected type in the chip (<code>txt (detected) · 14 KB</code>), tooltip on hover. No toast.</li></ul><h2 id="_5-what-we-re-killing" tabindex="-1">5. What we&#39;re killing <a class="header-anchor" href="#_5-what-we-re-killing" aria-label="Permalink to &quot;5. What we&#39;re killing&quot;">​</a></h2><ul><li>The tapia-specific UI components living inside <code>desktop/soma/src/renderer/src/routes/practice/components/</code>. Anything reusable migrates to <code>@soma/ui</code>; the rest dies.</li><li>Global box-shadows.</li><li>The current floating editor menu (replaced with a slash menu + selection bubble bar from <code>@soma/ui</code>).</li><li>Buttons-everywhere space settings. Replaced by tabbed settings (4.2).</li></ul><h2 id="_6-component-plan-for-soma-ui" tabindex="-1">6. Component plan for <code>@soma/ui</code> <a class="header-anchor" href="#_6-component-plan-for-soma-ui" aria-label="Permalink to &quot;6. Component plan for \`@soma/ui\`&quot;">​</a></h2><p>New / extended components, all built once for both <code>soma</code> and <code>practice</code> consumers:</p><table tabindex="0"><thead><tr><th>Component</th><th>Purpose</th><th>Status</th></tr></thead><tbody><tr><td><code>PanelContainer</code></td><td>Right-area stack + split host</td><td>new</td></tr><tr><td><code>Panel</code></td><td>Header + body + collapse/drag-handle</td><td>new</td></tr><tr><td><code>SlashMenu</code></td><td>Editor command palette. Sections: Text · List · Embed · Action · Advanced. <strong>No AI tile</strong> — AI goes through the right-area chat panel, a slash AI block would be a redundant trap</td><td>new</td></tr><tr><td><code>MentionPicker</code></td><td><code>@</code> autocomplete: Bots → Documents → Members. Keyboard-first</td><td>new</td></tr><tr><td><code>SelectionBubble</code></td><td>Inline formatting bar over editor selection. Single dark pill above selection; block-style dropdown leftmost</td><td>new</td></tr><tr><td><code>BotList</code></td><td>Bot list for space settings (status pill, capability scope, alias). <em>Renamed from <code>BotCatalogList</code> — there is no catalog; bots are added by paste</em></td><td>new</td></tr><tr><td><code>CapabilityForm</code></td><td>Identity / Scopes (collapsible groups with counts) / Expiry / Issue, one scroll surface</td><td>new</td></tr><tr><td><code>BackendSwitcher</code></td><td>ACP backend picker chip for the <strong>composer footer</strong> (was originally specced for chat header)</td><td>new</td></tr><tr><td><code>PeerAddressInput</code></td><td>Single-field paste + validate for bot adding</td><td>new</td></tr><tr><td><code>SpacesRail</code></td><td>52px icon rail with active indicator</td><td>refactor</td></tr><tr><td><code>CharDisplay</code></td><td>Existing typing visual</td><td>keep, extract any inline styles</td></tr><tr><td><code>DensityProvider</code></td><td>Tailwind context for compact / cozy toggle</td><td>new</td></tr><tr><td><code>Empty</code></td><td>Empty-state primitive with three variants: <strong>full</strong> (icon + headline + optional CTA), <strong>compact</strong> (dashed-border single line, for narrow panels), <strong>filter</strong> (CTA is <code>Clear filter ×</code>)</td><td>new</td></tr><tr><td><code>DenseRow</code></td><td>Shared list-row slot model: <code>leading · primary(+sub) · status pill · meta · always-visible ⋯</code>. Used by members, bots, attachments, recent docs</td><td>new</td></tr><tr><td><code>CommandPalette</code></td><td>⌘K modal: Recent docs (any space) → Spaces → Documents → Commands</td><td>new</td></tr><tr><td><code>TreePopover</code></td><td>Document-tree picker anchored under the last breadcrumb segment in the document column header. Built on <a href="https://www.npmjs.com/package/react-complex-tree" target="_blank" rel="noreferrer"><code>react-complex-tree</code></a> for keyboard nav, drag-and-drop reordering, and large-tree virtualization</td><td>new</td></tr><tr><td><code>PopupShell</code></td><td>Reusable popup-window chrome (drag strip + glyph cluster: pin / restart / return-to-main / close). Hosts <code>CharDisplay</code> in v0; exams/surveys later</td><td>new</td></tr><tr><td><code>SelectionAIBar</code></td><td>Inline AI popover above selection — prompt input + categorized action list (Rewrite / Modify / Tone / Transform / Translate / Custom). Trailing chip on <code>SelectionBubble</code> opens it</td><td>new</td></tr><tr><td><code>InlineAIAcceptBar</code></td><td><code>Accept · Try again · Refine… · Discard · Open in chat</code> bar anchored under inserted region after AI streams</td><td>new</td></tr><tr><td><code>NodeAIRegistry</code></td><td>Per-block-type AI action registry consumed by <code>SlashMenu</code>, <code>SelectionAIBar</code>, and the right-click block menu&#39;s <code>AI ▸</code> cluster</td><td>new</td></tr><tr><td><code>InlineAIStream</code></td><td>Streaming display primitive at the caret: accent underline + <code>Thinking…</code> pill + Stop chip. Region is <code>contenteditable=false</code> while streaming</td><td>new</td></tr></tbody></table><p>Detailed component specifications live in the locked patterns of the six refs docs (<a href="./ui-revamp-v0-refs">overview</a>, <a href="./ui-revamp-v0-refs-space-lifecycle">space lifecycle</a>, <a href="./ui-revamp-v0-refs-assistant-bots">assistant + bots</a>, <a href="./ui-revamp-v0-refs-editor">editor</a>, <a href="./ui-revamp-v0-refs-files-density">files + density</a>, <a href="./ui-revamp-v0-refs-popup-window">popup window</a>).</p><h2 id="_7-phased-delivery" tabindex="-1">7. Phased delivery <a class="header-anchor" href="#_7-phased-delivery" aria-label="Permalink to &quot;7. Phased delivery&quot;">​</a></h2><p><strong>Step 1 (this PRD).</strong> Vision + layout + flows in draft. ← <em>you are here</em><strong>Step 2.</strong> Refero inspiration pass on: 3-pane Notion clones, stackable side panels (Linear/Height), inline mention pickers, capability-grant UIs. Findings appended as <code>prd/ui-revamp-v0-refs.md</code>. <strong>Step 3.</strong> Flow drafts revised against refs, then locked. <strong>Step 4.</strong> ADR-0005 captures the locked architectural decisions (right-area panel system, single-UI consolidation, popup-window mechanism, settings IA). <strong>Step 5.</strong> Component scaffolding in <code>@soma/ui</code> (storybook stories for each new component before they ship to <code>soma</code>). <strong>Step 6.</strong> Cutover in <code>desktop/soma</code>: replace screens one at a time, behind no flag — branch is the gate. Start with space settings (4.2 + 4.4) since &quot;add a bot&quot; is v0 priority.</p><h2 id="_8-out-of-scope-for-v0" tabindex="-1">8. Out of scope for v0 <a class="header-anchor" href="#_8-out-of-scope-for-v0" aria-label="Permalink to &quot;8. Out of scope for v0&quot;">​</a></h2><ul><li>The known bugs (scrolling, floating menu, shadows, .txt MIME detection). The revamp deletes the code paths that caused them; we won&#39;t separately fix.</li><li>Density toggle UX (we ship dense; the toggle component is built but defaults to dense; cozy variant is post-v0).</li><li>End-to-end encryption per space (mentioned as future work in space-authorization-model.md).</li><li>Multi-window beyond typing popup. Architecture supports it; only typing ships in v0.</li></ul><h2 id="_9-resolved-decisions" tabindex="-1">9. Resolved decisions <a class="header-anchor" href="#_9-resolved-decisions" aria-label="Permalink to &quot;9. Resolved decisions&quot;">​</a></h2><ol><li><strong>Right area sizing.</strong> No fixed max width. Adaptive collapse: docked → drawer+overlay → fullscreen takeover, depending on window width (see §3 <em>Responsive behavior</em>). Editor is the priority surface.</li><li><strong>Very small screens.</strong> Panel fullscreen-takeover; editor hidden while a panel is active. Same component tree, different layout slot.</li><li><strong>Bot adding ≠ discovery.</strong> Bots are added manually by pasting a peer address (see §4.4). RBAC governs who can add and with what scope. Daemon-side handshake + encryption + registration. <strong>Backend item to verify:</strong> whether <code>soma-daemon</code> already enumerates / persists registered bots per-space; if not, build it in parallel with the UI.</li><li><strong>LLM provider scope.</strong> <strong>Agent Client Protocol (ACP)</strong>, same as Zed. Backends supported: Ollama, LM Studio, Codex, OpenAI-compatible (via ACP shim).</li><li><strong>Backend switcher lives in the composer footer</strong>, not the chat header. Saves vertical chrome and puts the control where the user&#39;s eye is when picking a backend (§4.5).</li><li><strong>Settings auto-save on blur.</strong> No global Save button anywhere in space settings; per-section Save buttons are banned. Errors surface inline (§4.2).</li><li><strong>Density: 1.5 body line-height, 1px borders, one shadow token.</strong> Concrete numbers in §3 and the density refs doc.</li><li><strong>No AI tile in the slash menu.</strong> AI goes through the right-area chat. A slash AI block would duplicate intent across surfaces (§6).</li><li><strong><code>Empty</code> has three variants</strong> (full / compact / filter); used everywhere instead of ad-hoc empty-state markup (§6).</li><li><strong><code>DenseRow</code> is the single list-row primitive</strong> used by members, bots, attachments, recent docs (§6).</li><li><strong>Popup windows have a reusable shell</strong> (<code>PopupShell</code>) — drag strip + glyph cluster (pin / restart / return-to-main / close). v0 hosts <code>CharDisplay</code>; future exams/surveys reuse the shell (§4.7).</li></ol><hr><p><em>This PRD is the source of truth until decisions are lifted into ADR-0005. Edit freely until lock.</em></p>`,75)])])}const m=t(n,[["render",r]]);export{u as __pageData,m as default};
